def dict_depth(d):
    """Write a function to find the depth of a dictionary.

    A dictionary has depth 1 if it contains no nested dictionaries,
    including when it is empty. Each additional level of nested
    dictionary adds 1, and the depth is determined by the most deeply
    nested dictionary. Non-dictionary values have depth 0, so they do
    not add a level.

    Example:
        dict_depth({'a': 1, 'b': {'c': {'d': {}}}}) == 4
    """
    if not isinstance(d, dict):
        return 0
    if not d:
        return 1
    return 1 + max(dict_depth(value) for value in d.values())
